  private _setOverlayTargetOpacity(
    target: HTMLElement | null,
    opacity: number,
  ): void {
    if (!target) return;
    const clampedOpacity = Helpers.clamp01(opacity);
    this._applyDomVisibilityState(target, {
      visible: clampedOpacity > 0.001,
      opacity: clampedOpacity,
    });
  }

  private _isActiveSceneState<
    TSceneKey extends string,
    TSheetId extends string,
  >(
    sceneKey: TSceneKey,
    sheetId: TSheetId | null,
    expectedState: SceneActiveState<TSceneKey, TSheetId>,
  ): boolean {
    if (sceneKey !== expectedState.sceneKey) return false;
    if (sheetId !== expectedState.sheetId) return false;
    return true;
  }

  private _resolveTransitionWindowValue<
    TSceneKey extends string,
    TSheetId extends string,
  >(
    sceneKey: TSceneKey | null,
    progress: number,
    sheetId: TSheetId | null,
    window: SceneProgressTransitionWindow<TSceneKey, TSheetId>,
  ): number | null {
    if (sceneKey !== window.sceneKey) return null;
    if (sheetId !== window.sheetId) return null;
    const normalizedProgress = Helpers.remap01(
      progress,
      window.start,
      window.end,
    );
    const easedProgress = this._applyTransitionEase(
      normalizedProgress,
      window.easing ?? "linear",
    );
    return Helpers.lerpClamped(window.from, window.to, easedProgress);
  }

  private _applyTransitionEase(
    value: number,
    easing: TransitionEaseKey,
  ): number {
    if (easing === "easeInOutCubic") {
      return this._easeInOutCubic(value);
    }
    return Helpers.clamp01(value);
  }

  private _easeInOutCubic(value: number): number {
    const clampedValue = Helpers.clamp01(value);
    if (clampedValue < 0.5) return 4 * clampedValue * clampedValue * clampedValue;
    const shiftedValue = -2 * clampedValue + 2;
    return 1 - (shiftedValue * shiftedValue * shiftedValue) / 2;
  }

  private _applyDomVisibilityState(
    element: HTMLElement,
    state: DomVisibilityState,
  ): void {
    if (state.opacity != null) {
      element.style.opacity = String(Helpers.clamp01(state.opacity));
    }
    Aria.setVisibility(element, state.visible);
  }
}

